CREATE DATABASE IF NOT EXISTS medislot;
USE medislot;

-- Final MediSlot schema. IDs are UUID strings generated by the application.

CREATE TABLE IF NOT EXISTS hospitals (
    hospital_id CHAR(36) PRIMARY KEY,
    hospital_name VARCHAR(255) NOT NULL,
    branch_name VARCHAR(255),
    address_line1 VARCHAR(255) NOT NULL,
    address_line2 VARCHAR(255),
    city VARCHAR(100) NOT NULL,
    state VARCHAR(100) NOT NULL,
    postal_code VARCHAR(20),
    country VARCHAR(100) NOT NULL DEFAULT 'India',
    timezone VARCHAR(64) NOT NULL DEFAULT 'Asia/Kolkata',
    phone VARCHAR(20),
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3)
);

CREATE TABLE IF NOT EXISTS doctors (
    doctor_id CHAR(36) PRIMARY KEY,
    registration_number VARCHAR(100) NOT NULL UNIQUE,
    first_name VARCHAR(100) NOT NULL,
    last_name VARCHAR(100) NOT NULL,
    email VARCHAR(255) NOT NULL UNIQUE,
    password_hash VARCHAR(255) NOT NULL,
    qualification VARCHAR(255),
    experience_years SMALLINT UNSIGNED NOT NULL DEFAULT 0,
    profile_photo_url VARCHAR(500),
    profile_status ENUM('PENDING','ACTIVE','INACTIVE') NOT NULL DEFAULT 'PENDING',
    created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3)
);

CREATE TABLE IF NOT EXISTS patients (
    patient_id CHAR(36) PRIMARY KEY,
    first_name VARCHAR(100) NOT NULL,
    last_name VARCHAR(100),
    email VARCHAR(255) NOT NULL UNIQUE,
    password_hash VARCHAR(255) NOT NULL,
    date_of_birth DATE,
    gender VARCHAR(30),
    phone VARCHAR(20),
    created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3)
);

CREATE TABLE IF NOT EXISTS specialisations (
    specialisation_id CHAR(36) PRIMARY KEY,
    specialisation_name VARCHAR(150) NOT NULL UNIQUE,
    description VARCHAR(500),
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)
);

CREATE TABLE IF NOT EXISTS doctor_specialisations (
    doctor_id CHAR(36) NOT NULL,
    specialisation_id CHAR(36) NOT NULL,
    created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    PRIMARY KEY (doctor_id, specialisation_id),
    CONSTRAINT fk_ds_doctor FOREIGN KEY (doctor_id) REFERENCES doctors(doctor_id),
    CONSTRAINT fk_ds_specialisation FOREIGN KEY (specialisation_id) REFERENCES specialisations(specialisation_id)
);

CREATE TABLE IF NOT EXISTS doctor_hospitals (
    doctor_hospital_id CHAR(36) PRIMARY KEY,
    doctor_id CHAR(36) NOT NULL,
    hospital_id CHAR(36) NOT NULL,
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    UNIQUE KEY uq_doctor_hospital (doctor_id, hospital_id),
    CONSTRAINT fk_dh_doctor FOREIGN KEY (doctor_id) REFERENCES doctors(doctor_id),
    CONSTRAINT fk_dh_hospital FOREIGN KEY (hospital_id) REFERENCES hospitals(hospital_id)
);

CREATE TABLE IF NOT EXISTS consultation_types (
    consultation_type_id CHAR(36) PRIMARY KEY,
    type_name VARCHAR(100) NOT NULL UNIQUE,
    duration_minutes SMALLINT UNSIGNED NOT NULL,
    capacity SMALLINT UNSIGNED NOT NULL DEFAULT 1,
    description VARCHAR(500),
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    consultation_fee DECIMAL(10,2) NOT NULL DEFAULT 0.00,
    created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    CHECK (duration_minutes > 0),
    CHECK (capacity > 0)
);

-- Weekly availability times are stored and interpreted as UTC.
CREATE TABLE IF NOT EXISTS doctor_availability (
    availability_id CHAR(36) PRIMARY KEY,
    doctor_id CHAR(36) NOT NULL,
    hospital_id CHAR(36) NOT NULL,
    consultation_type_id CHAR(36) NOT NULL,
    day_of_week TINYINT UNSIGNED NOT NULL,
    start_time TIME NOT NULL,
    end_time TIME NOT NULL,
    effective_from DATE NOT NULL,
    effective_until DATE NULL,
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
    CONSTRAINT fk_da_doctor FOREIGN KEY (doctor_id) REFERENCES doctors(doctor_id),
    CONSTRAINT fk_da_hospital FOREIGN KEY (hospital_id) REFERENCES hospitals(hospital_id),
    CONSTRAINT fk_da_consultation FOREIGN KEY (consultation_type_id) REFERENCES consultation_types(consultation_type_id),
    CHECK (day_of_week BETWEEN 0 AND 6),
    CHECK (end_time > start_time)
);

CREATE TABLE IF NOT EXISTS doctor_blackouts (
    blackout_id CHAR(36) PRIMARY KEY,
    doctor_id CHAR(36) NOT NULL,
    hospital_id CHAR(36) NULL,
    start_at_utc DATETIME(3) NOT NULL,
    end_at_utc DATETIME(3) NOT NULL,
    reason VARCHAR(255),
    created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    CONSTRAINT fk_db_doctor FOREIGN KEY (doctor_id) REFERENCES doctors(doctor_id),
    CONSTRAINT fk_db_hospital FOREIGN KEY (hospital_id) REFERENCES hospitals(hospital_id),
    CHECK (end_at_utc > start_at_utc)
);

CREATE TABLE IF NOT EXISTS appointments (
    appointment_id CHAR(36) PRIMARY KEY,
    patient_id CHAR(36) NOT NULL,
    doctor_id CHAR(36) NOT NULL,
    hospital_id CHAR(36) NOT NULL,
    consultation_type_id CHAR(36) NOT NULL,
    slot_id VARCHAR(255) NOT NULL,
    start_at_utc DATETIME(3) NOT NULL,
    end_at_utc DATETIME(3) NOT NULL,
    status ENUM('CONFIRMED','COMPLETED','CANCELLED','NO_SHOW','RESCHEDULED') NOT NULL DEFAULT 'CONFIRMED',
    reschedule_count TINYINT UNSIGNED NOT NULL DEFAULT 0,
    cancelled_at_utc DATETIME(3) NULL,
    created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
    CONSTRAINT fk_ap_patient FOREIGN KEY (patient_id) REFERENCES patients(patient_id),
    CONSTRAINT fk_ap_doctor FOREIGN KEY (doctor_id) REFERENCES doctors(doctor_id),
    CONSTRAINT fk_ap_hospital FOREIGN KEY (hospital_id) REFERENCES hospitals(hospital_id),
    CONSTRAINT fk_ap_consultation FOREIGN KEY (consultation_type_id) REFERENCES consultation_types(consultation_type_id),
    INDEX idx_doctor_start (doctor_id, start_at_utc),
    INDEX idx_patient_start (patient_id, start_at_utc)
);

CREATE TABLE IF NOT EXISTS refund_ledger (
    refund_id CHAR(36) PRIMARY KEY,
    appointment_id CHAR(36) NOT NULL,
    cancellation_type ENUM('PATIENT','DOCTOR') NOT NULL,
    original_fee DECIMAL(10,2) NOT NULL,
    refund_percentage DECIMAL(5,2) NOT NULL,
    refund_amount DECIMAL(10,2) NOT NULL,
    created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    CONSTRAINT fk_refund_appointment FOREIGN KEY (appointment_id) REFERENCES appointments(appointment_id),
    CHECK (refund_percentage BETWEEN 0 AND 100)
);
